fun main() {
    println("a,b,,c".split(","))
    println("a,b,c".split(",", limit = 2))
    println("abc".split(""))
    println("a-b_c".split('-', '_'))
    println("a1b2c".split("1", "2"))
    println("AbC".split("b", ignoreCase = true))
    println("abc".windowed(2))
    println("abcde".windowed(2, 2, true))
    println("abc".zip("xyz"))
    println("a-b-c".replaceFirst("-", "+"))
    println("Hello".replace("L", "_", ignoreCase = true))
    println("  hi\n".trimMargin())
    println("""
        |first
        |  second
    """.trimMargin())
    println("abc".prependIndent("> "))
    println("kotlin".replaceFirstChar { it.uppercaseChar() })
    println("abcdef".substring(1..3) + "abcdef".slice(0..1) + "abcdef".removeRange(1..4))
    println("hello".commonSuffixWith("jello"))
    println("a\nb\r\nc".lineSequence().toList())
    println("abc".startsWith("AB", ignoreCase = true))
    println("abc".contains("BC", true))
    println("abc".indexOf("c", 0, false))
    println("hello".replaceBefore("l", "J") + "hello".replaceAfter("l", "J"))
    println("abc".toSet())
    println("hello world".groupBy { it }.mapValues { it.value.size }.filter { it.value > 1 })
    println("abc".partition { it == 'a' })
    println("zebra".maxOrNull())
    println("3.5".toFloat())
    println("abc".compareTo("ABD", ignoreCase = true))
    println('7'.digitToIntOrNull())
    println("hello".asSequence().filter { it != 'l' }.joinToString(""))
}
